select dept_name, case when budget >= 3302000 then 'high' when budget >= 870000 then 'mid' else 'low' end as budget_bucket, sum(budget) as total_budget, count(budget) as budget_count from departments where location = 'Berlin' and dept_name in ('Engineering', 'Sales', 'Legal') and location in ('London', 'Berlin', 'Chiang Mai') group by 1, 2 having total_budget > 8145000 order by budget_bucket, 1 limit 10;
